Here's the Python code to achieve this:

```python
from collections import deque

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def ladoos(root, home, K):
    if not root:
        return 0

    queue = deque([(root, 0)])
    visited = set()
    total_ladoos = 0

    while queue:
        node, dist = queue.popleft()

        if node.val == home:
            total_ladoos = node.val
            K = dist

        if node.val not in visited:
            visited.add(node.val)
            total_ladoos += node.val

            if node.left and dist + 1 <= K:
                queue.append((node.left, dist + 1))
            if node.right and dist + 1 <= K:
                queue.append((node.right, dist + 1))

    return total_ladoos
